import java.util.*;

import org.slf4j.*;

public class Main {
    public static void main(String[] args) {
        Gudang gudang = new Gudang();
        gudang.ambil("Pensil", 3);
        gudang.ambil("Buku", 10);
    }
}

class Gudang {
    private static final Logger log = LoggerFactory.getLogger(Gudang.class);
    private final Map<String, Integer> stok = new HashMap<>();

    Gudang() {
        stok.put("Pensil", 20);
        stok.put("Buku", 5);
    }

    void ambil(String barang, int jumlah) {
        int ada = stok.get(barang);
        if (jumlah > ada) {
            System.out.println("stok " + barang + " kurang");
            log.warn("Stok {} kurang: diminta {}, tersedia {}", barang, jumlah, ada);
            return;
        }
        stok.put(barang, ada - jumlah);
        log.info("{} diambil {}, sisa {}", barang, jumlah, ada - jumlah);
    }
}

